from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW18SP.autoconnection import AutoConfiguration
from taf.fdsw.rc.schemas.FDSW18A.autoconnection import (AutoConnection,
                                                        Site_Identification18A)


class AutoConfiguration18A(AutoConfiguration):

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        get_autoconnection_parameters = AutoConnection.from_object_dict(data=autoconnection.data)
        return get_autoconnection_parameters.to_dict()

    def set_site_identification(self, autoconnection_site_id, timeout=10):
        set_site_identification_response = self._client.send(
            method='config.identification.update',
            timeout=timeout,
            parameters={'siteId': autoconnection_site_id})
        if set_site_identification_response.status is False:
            error_msg = "Set identification siteId information is not valid. Error: {}"
            raise OperationFailure(error_msg.format(
                autoconnection_site_id,
                set_site_identification_response.error
            ))

    def get_site_identification_siteId(self, timeout=10):
        get_site_identification_siteId = self._client.send(
            method='config.identification.fetch',
            timeout=timeout,
            parameters={})
        if get_site_identification_siteId.status is False:
            error_msg = "Get identification siteId information is not valid. Error: {}"
            raise OperationFailure(error_msg)
        get_site_identification_siteId = Site_Identification18A.from_object_dict(data=get_site_identification_siteId.data)
        return get_site_identification_siteId.siteId
